// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the sender address and the value to send. The general rule:
    // For any caller and any positive value, calling receive (sending ETH) should succeed
    // and increase depositsCount (and contract balance) in the reference; the mutant's
    // require(false) breaks that for some inputs (e.g., any positive value).
    function testFuzz_property(address sender, uint256 value) public {
        // restrict value to a reasonable wide domain but include positives
        // we want to let fuzzer find positive amounts, so allow 1..1e30 roughly
        uint256 amt = bound(value, 0, 1e30);

        // Ensure the sender has funds to send when amt > 0
        if (amt > 0) {
            vm.deal(sender, amt);
        }

        // Make the call as sender to trigger receive()
        bool ok;
        // perform the action and observe whether the receive succeeded
        if (amt > 0) {
            vm.prank(sender);
            // try-catch not directly available for plain ether transfer; call c with value
            try this.doSend{value: 0}(sender, amt) returns (bool success) {
                ok = success;
            } catch {
                ok = false;
            }
        } else {
            // if amt == 0, sending zero may still invoke receive; allow it
            vm.prank(sender);
            try this.doSend{value: 0}(sender, amt) returns (bool success) {
                ok = success;
            } catch {
                ok = false;
            }
        }

        // The universal property we assert: if the send had a positive value, the call must succeed
        // and depositsCount must increase by 1 and balance must increase by amt for the reference.
        // We observe c only via public getters. We assert that for the chosen fuzz inputs,
        // the receive succeeded (ok == true) OR amt == 0 (zero-value sends are allowed but may be no-op).
        // The single assertion below captures that positive transfers succeed on the reference
        // but fail on the mutant (thus the test will fail on the mutant for some amt>0).
        assertTrue(amt == 0 || ok);
    }

    // helper function used so we can try/catch the external call to c with value
    // this function performs the low-level sending to c (so try/catch in testFuzz_property works)
    function doSend(address sender, uint256 amt) public payable returns (bool) {
        // forward the ether to c; this contract must send the value it holds
        // we received no ether here; instead, perform a call from msg.sender (which is vm.prank(sender) in the caller)
        // Use address(c).call{value: amt}("") to trigger receive()
        (bool success, ) = address(c).call{value: amt}("");
        return success;
    }
}

