pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: an address sender and an amount of wei to send.
    // General rule: for any caller address and any positive amount, calling receive() (by sending ETH)
    // to the reference contract succeeds (does not revert) and thus the transaction completes.
    // The mutant with `require(false)` in receive() will revert for any positive amount,
    // so the property distinguishes them.
    function testFuzz_property(address sender, uint256 amount) public {
        // Keep amount in a sensible wide domain but require it be > 0 (the meaningful case).
        vm.assume(amount > 0);
        // Avoid using the zero address as a sender for practicality (fuzzer may produce it).
        vm.assume(sender != address(0));

        // Fund the sender so they can send `amount` wei to c.
        vm.deal(sender, amount);

        // Act: have sender send ETH to c to trigger receive()
        bool ok;
        vm.prank(sender);
        try c.call{value: amount}("") {
            // low-level call succeeded (should map to receive succeeding)
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract's receive accepts any positive amount (increments depositsCount and does not revert),
        // so for all admissible inputs (sender != 0, amount > 0) ok should be true. The mutant that always reverts
        // in receive will make ok == false for some inputs (indeed for any positive amount).
        assertTrue(ok);
    }
}

