import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: sender address and amount of ETH to send
    function testFuzz_property(address sender, uint256 amount) public {
        // keep amount in a reasonable domain (non-zero and not absurdly large)
        vm.assume(sender != address(0));
        amount = bound(amount, 1, address(this).balance + 1 ether);

        // fund the sender so it can send ETH
        vm.deal(sender, amount);

        bool ok;
        // perform the external action: send ETH to c via its receive()
        vm.prank(sender);
        try payable(address(c)).call{value: amount}("") {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule (reference): for any sender and any positive amount, receive() succeeds
        // i.e., ok is always true on the reference implementation. The mutant that has `require(false)`
        // in receive() will cause ok==false for some positive amounts. We assert on ok (reading c via its
        // observable behavior through the receive call success) — a single assertion as required.
        assertTrue(ok);
    }
}

