        // avoid the zero address as sender for clarity (EOA-like)
        vm.assume(sender != address(0));

        // fund the sender so it can send ETH
        vm.deal(sender, amount);

        // perform the payable call to C.receive by sending raw ETH from sender
        bool ok;
        vm.prank(sender);
