pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: amount to send and an address for the caller (pranked actor)
    // We need an adversarial counterparty: a contract that reverts on receiving funds
    function testFuzz_property(uint256 amount, address sender) public {
        // keep amount in a reasonable wide domain but non-zero so receive gets payable value
        amount = bound(amount, 0, 1 ether);
        // Ensure sender is a non-zero address usable by vm.prank
        if (sender == address(0)) sender = address(0xBEEF);

        // Deploy a helper that will revert in its fallback/receive to create a scenario
        // where an external call or transfer might fail. Here we will instead simulate
        // sending to c's receive from the sender; the reference has an extra require
        // that prevents overflow-like behavior; to exercise a difference we rely on
        // the fact that the reference's require may cause a revert for certain
        // arithmetic edge cases — to be conservative, we still run the call normally.

        // Fund the sender to allow sending
        vm.deal(sender, amount);
        vm.prank(sender);

        // Call c.receive by sending value to the contract
        bool ok;
        try c{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: if the call returned (ok == true), then
        // depositsCount was incremented exactly by 1 compared to 0 (initial state is 0).
        // The reference satisfies: after any successful receive call, depositsCount == 1.
        // The mutant that unconditionally increments might cause differing behavior
        // for inputs that cause a revert in the reference but not in the mutant.
        // We therefore assert that when the call succeeded, depositsCount == 1.
        assertTrue(!ok || c.depositsCount() == 1);
    }
}

