pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the amount to send; an adversarial recipient contract will revert when it is the target
    function testFuzz_property(uint256 amount) public {
        // keep amount in a reasonable range but wide enough to include nonzero
        amount = bound(amount, 0, 1 ether);

        // deploy a reverting counterparty; it will revert in its payable fallback/receive
        Reverter r = new Reverter();

        // give the fuzzer-controlled actor some balance and act as it
        address payer = address(0xBEEF);
        vm.deal(payer, amount);
        vm.prank(payer);

        // Now call c.sendMoney(...) which in C uses a low-level call to the target
        // We route the low-level call to the Reverter so that the call reverts.
        // If C is the reference, the receive() will only increment depositsCount when the low-level call did NOT revert.
        // But here the low-level call (to Reverter) will revert, so the reference's depositsCount should NOT increment;
        // the mutant removed the require guard and would increment unconditionally, causing a difference.
        // To trigger C.receive, we must send Ether to C; C.receive increments and then does the low-level call.

        // Send Ether to c to trigger receive()
        // Use a try/catch around the low-level sendMoney to capture reverts of the external call if any
        // We call sendMoney with the reverter address so that C's internal low-level call fails.
        // Note: the top-level send to c (to invoke receive) should succeed (unless C reverts internally),
        // so we send value 'amount' from payer to c.

        // First, record depositsCount before
        uint before = c.depositsCount();

        // perform the payment to c to invoke receive()
        vm.prank(payer);
        (bool ok, ) = address(c).call{value: amount}("");
        // ok indicates whether the external call to c (the receive) succeeded
        // In the reference contract, receive will attempt the low-level call to Reverter which will revert;
        // that revert will bubble up and make the whole receive revert, so ok == false, and depositsCount should remain unchanged.
        // In the mutant, receive increments before the failed external call, so even though the low-level call reverts,
        // the mutant's receive may still revert the outer call but depositsCount would have been incremented.

        uint after = c.depositsCount();

        // General rule: for ANY amount (including zero) the reference C ensures that if the external call inside receive reverts,
        // then depositsCount is NOT incremented (i.e., after == before). The mutant violates this for some inputs (here when the callee reverts).
        // We assert the property by checking that either the outer call succeeded and depositsCount increased by 1,
        // or the outer call reverted and depositsCount did not increase. For the reference implementation, when the internal low-level call reverts,
        // the outer call reverts and therefore depositsCount must remain equal to before. This assertion holds for the reference for all inputs,
        // and the mutant will fail it for some input (when the inner call reverts but mutant already incremented depositsCount).

        // Express the universal property as a single boolean observation about c: if the external call failed (ok == false) then depositsCount == before,
        // else if it succeeded then depositsCount == before + 1.
        bool prop = (ok == false && after == before) || (ok == true && after == before + 1);
        assertTrue(prop);
    }
}

contract Reverter {
    receive() external payable { revert("revert"); }
}

