pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to send and a bool that chooses whether the helper will revert
    function testFuzz_property(uint256 amount, bool doRevert) public {
        // keep amount within a sensible range but wide
        amount = bound(amount, 0, 1 ether);

        // deploy adversarial helper that either accepts or reverts on receive
        ReverterOrAcceptor helper = new ReverterOrAcceptor(doRevert);

        // fund the helper so it can attempt forwarding if needed (not necessary here, but safe)
        vm.deal(address(this), 1 ether);

        // Prepare sender as the helper; helper will forward a call to c's receive by calling selfdestruct? No,
        // we simply make the helper receive ether from this test and then the helper will attempt to call c
        // so that c receives Ether from an address that can revert on receive.

        // Send Ether to c from the helper contract to trigger c.receive()
        // To have the helper initiate the call, we fund it and call its doCall function.
        vm.deal(address(helper), amount + 1);

        // helper will attempt to call c with the specified amount; if helper is configured to revert in its
        // receive, the call into c will come from helper but the helper's own receive behavior matters only
        // for external adversarial behaviors. Here helper does a low-level call to c and may revert before or after.

        // Have helper invoke c.receive by low-level call from helper
        bool ok;
        try helper.callReceive{value: amount}(address(c)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general property: after attempting such a call, the reference contract will have depositsCount
        // equal to the number of successful receive() executions; in particular, if the external call into c
        // reverted then reference C did not increment depositsCount. We assert that depositsCount is either 0
        // or 1 and matches whether the call completed successfully. This reads c's public getter.
        // Exactly one assertion as required.
        // ok == true means the low-level call from helper to c succeeded, so depositsCount should be 1 when amount>0
        // but reference contract increments only when call completes; because amount can be zero, the safe universal
        // property is: depositsCount == (ok ? 1 : 0) when starting from fresh contract with zero initial deposits.

        // read depositsCount
        uint256 deposits = c.depositsCount();
        assertTrue(deposits == (ok ? 1 : 0));
    }
}

contract ReverterOrAcceptor {
    bool public doRevert;
    constructor(bool _doRevert) payable { doRevert = _doRevert; }

    // this contract will call c by sending ether to it via low-level call
    function callReceive(address target) external payable {
        // attempt to call the target's receive
        (bool success, ) = target.call{value: msg.value}("");
        if (!success) revert("call failed");
    }

    // fallback/receive for safety (not strictly needed)
    receive() external payable {
        if (doRevert) revert("I revert on receive");
    }
}

