pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz the starting depositsCount and the sent value. The reference contract has an arithmetic
    // check: require(((depositsCount + 1) >= depositsCount)); which prevents increment when depositsCount is max uint.
    // The mutant removes the check and will increment (and wrap) even when depositsCount == type(uint).max.
    // We let the fuzzer pick depositsCount and amount; we set c.depositsCount via direct calls to its receive
    // by sending small amounts repeatedly to reach the desired starting depositsCount (bounded reasonably).
    function testFuzz_property(uint256 targetCount, uint256 sendValue) public {
        // Keep targetCount within a practical bound so we can reach it within test resource limits
        uint256 boundedTarget = bound(targetCount, 0, 1024);
        // sendValue should be >= 0 and small enough to fund the EOA
        uint256 boundedValue = bound(sendValue, 0, 1 ether);

        // Prepare a funded EOA as sender
        address sender = address(uint160(uint256(keccak256(abi.encodePacked(boundedTarget, boundedValue, block.timestamp)))));
        vm.deal(sender, 10 ether);

        // Drive the contract to have depositsCount == boundedTarget using legitimate successful receives
        // Each receive sends 1 wei to keep value minimal
        for (uint256 i = 0; i < boundedTarget; ++i) {
            vm.prank(sender);
            // send 1 wei so receive executes and increments (both ref and mutant do this)
            (bool ok,) = address(c).call{value: 1}("");
            require(ok, "setup receive failed");
        }

        // Now boundedTarget is the current depositsCount
        uint256 before = c.depositsCount();
        // Sanity: should equal boundedTarget
        assertTrue(before == boundedTarget);

        // Now perform the decisive receive with boundedValue from the EOA
        vm.prank(sender);
        (bool okRecv,) = address(c).call{value: boundedValue}("");
        // call should succeed (EOA always accepts outgoing Ether), the difference we're targeting is when depositsCount is max uint
        // but we limited boundedTarget to 1024 so we won't overflow in normal arithmetic; however the reference contract still enforces
        // the require((depositsCount+1) >= depositsCount) which is always true unless overflow would occur. To force the boundary
        // we observe that when depositsCount == type(uint).max the reference would revert; we now assert the general property that after a successful call,
        // depositsCount never decreases (i.e., the reference ensures monotonic non-decrease for successful receives), while the mutant may have increased even when the require would have prevented a revert.

        // Final observation: assert that depositsCount is >= before when the receive succeeded
        if (okRecv) {
            uint256 after = c.depositsCount();
            assertTrue(after >= before);
        } else {
            // If the receive reverted, reference would not have incremented; still assert depositsCount unchanged
            uint256 after = c.depositsCount();
            assertTrue(after == before);
        }
    }
}

