pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz a sender and an amount; the property: after a payable receive, depositsCount >= before
    function testFuzz_property(address sender, uint256 amount) public {
        // keep amount within reasonable bounds but allow zero as admissible input
        amount = bound(amount, 0, 1 ether);

        // fund the sender so it can send value
        vm.deal(sender, amount);

        // record before
        uint256 beforeCount = c.depositsCount();

        // perform the payable receive from fuzzed sender with fuzzed amount
        vm.prank(sender);
        // call into receive by sending value directly to the contract
        (bool ok, ) = address(c).call{value: amount}("");
        // we don't assert on ok here; even if call fails, the state should reflect that no successful receive happened

        uint256 afterCount = c.depositsCount();

        // General rule: a successful payable receive (i.e., when contract accepts funds) does not decrease depositsCount.
