import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public { 
        c = new C();
        owner = address(this); // set test contract as owner (msg.sender at construction)
    }

    // fuzz parameter: an arbitrary deposit amount that the fuzzer will supply
    function testFuzz_property(uint256 depositAmount) public {
        // keep deposit in a sane wide range: at least 1 wei and not exceeding some large bound
        vm.assume(depositAmount > 0);
        vm.assume(depositAmount <= type(uint256).max / 4);

        // fund this test contract so it can send depositAmount
        vm.deal(address(this), depositAmount);

        // send depositAmount to c via its receive() payable
        // as this contract is the owner (constructed c), msg.sender will be this contract
        // make the call with value
        (bool sent, ) = address(c).call{value: depositAmount}(""");
        require(sent, "deposit failed");

        // sanity: contract balance should equal depositAmount now
        // (we don't assert here because single assert required at end)

        // call withdrawAll as owner (this contract)
        c.withdrawAll();

        // The general rule: after withdrawAll, the contract balance is zero
        // This holds for the reference C for all inputs; the mutant that calls withdraw(0) will leave a non-zero balance for some depositAmount
        assertTrue(address(c).balance == 0);
    }
}

