import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); }

    // fuzz the amount to withdraw and an extra fund amount to seed the contract
    function testFuzz_property(uint256 seedFund, uint256 withdrawAmt) public {
        // keep seedFund within reasonable bounds and >0 so contract has balance
        seedFund = bound(seedFund, 1, 1 ether);
        // withdrawAmt can be up to 2 ether to allow attempts that exceed balance
        withdrawAmt = bound(withdrawAmt, 0, 2 ether);

        // deploy an attacker contract whose receive will revert, causing low-level call to fail
        attacker = new Attacker();

        // fund the contract c so withdraw can attempt to send
        vm.deal(address(this), seedFund);
        // send seedFund to c via its receive
        c.call{value: seedFund}("");

        // make c.owner be this contract? In C the owner is msg.sender at deployment; setUp deployed c from this test, so test contract is owner.

        // Now attempt to withdraw to the attacker address by making the test contract the caller but having the attacker be the recipient
        // The reference contract uses transfer to msg.sender, so to route funds to attacker we need attacker to be msg.sender in withdraw call.
        // Use prank to have attacker call withdraw; first give attacker some ETH to be able to be msg.sender
        vm.deal(address(attacker), 0);

        // attacker will call c.withdraw; when c tries to send to msg.sender (attacker), the attacker fallback will revert.
        // For the reference (using transfer) that revert will propagate and withdraw will revert; for mutant (using call) it will swallow failure and return success=false,
        // leaving contract balance unchanged but not reverting. We observe this by catching whether withdraw reverted and by checking contract balance.

        bool ok;
        // perform the call as attacker
        vm.prank(address(attacker));
        try c.withdraw(withdrawAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // single assertion: for the reference contract using transfer, any call to withdraw by the owner (attacker is NOT the owner) would revert; but we deployed c from this test so owner == address(this).
        // To trigger the key difference we must have the owner call withdraw while the receiver (msg.sender) is a reverting contract. Achieve by having this test contract be owner and forward a call from attacker via a delegate-style: instead, we emulate the owner calling withdraw but set msg.sender to attacker using tx.origin cannot be changed; simpler: make attacker the owner by deploying a fresh C where owner==attacker.
        // However we must follow the required single assertion pattern and observe c only. To correct flow, redeploy c such that owner is attacker.
    }
}

