pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz: amount to withdraw and a nonzero initial funding amount
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // keep values in wide but reasonable ranges
        depositAmount = bound(depositAmount, 0, 1 ether);
        withdrawAmount = bound(withdrawAmount, 0, 1 ether);

        // Deploy a callee that always reverts on receive/call to simulate a failing recipient
        Reverter rev = new Reverter();

        // Fund the contract with depositAmount from owner (setUp deployer is owner)
        if (depositAmount > 0) {
            vm.deal(address(this), depositAmount);
            vm.prank(address(this));
            // send Ether to contract via receive
            (bool sent,) = address(c).call{value: depositAmount}("");
            require(sent);
        }

        // owner must be msg.sender — set prank to the owner (creator) which is this test contract
        vm.prank(address(this));

        // If withdrawAmount > contract balance, the reference will attempt to transfer and may revert due to transfer failing
        // We try to withdraw to the Reverter address by calling c.sendMoney(rev, withdrawAmount) first to ensure path exists
        // But withdraw sends to msg.sender; to make msg.sender be a reverting address we simulate by having this contract call c.withdraw
        // while the recipient (owner) is a contract that reverts on receive. To do that, we need the owner to be rev, but owner is fixed to deployer.
        // Instead, we observe the invariant on contract balance after calling withdraw when msg.sender is the owner (this contract).
        // We simulate a failing recipient by having this contract forward the withdrawn funds to rev inside its receive —
        // deploy Forwarder owned by this test which in its receive forwards to Reverter (causing transfer to revert on REFERENCE)

        Forwarder fwd = new Forwarder(address(rev));

        // change prank to the forwarder so that msg.sender for withdraw is the forwarder (which is the owner? cannot change owner)
        // Owner is fixed to test contract (deployer). So to make owner be a contract that reverts on receive, we must have deployed C from an account that we control.
        // However setUp deployed c from this test contract; owner == address(this). To test behavior where transfer to owner reverts, we make this test contract's receive revert — but test contracts cannot change at runtime.
        // Alternate approach: call withdraw and observe that reference contract will either revert when transfer fails or succeed and reduce balance; the mutant may succeed but leave balance unchanged. We detect when withdraw returns (no revert) but balance unchanged — which only occurs in mutant.

        // Record balance before
        uint256 before = address(c).balance;

        bool ok;
        // call withdraw as owner (this contract)
        try c.withdraw(withdrawAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 after = address(c).balance;

        // General rule: for the reference contract, whenever withdraw returns (ok == true) it transferred the requested amount (so after == before - withdrawAmount, bounded by before)
        // We assert that if the call returned successfully then contract balance decreased by min(withdrawAmount, before).
        uint256 expectedDecrease = withdrawAmount;
        if (expectedDecrease > before) expectedDecrease = before;

        // single assertion observing c's public behavior
        assertTrue(!ok || after == before - expectedDecrease);
    }
}

// Helper that always reverts on any call/receive
contract Reverter {
    fallback() external payable { revert("revert"); }
    receive() external payable { revert("revert"); }
}

// Forwarder that forwards received Ether to a target (not used in final assertion but kept minimal per instructions)
contract Forwarder {
    address target;
    constructor(address _target) { target = _target; }
    receive() external payable {
        (bool s, ) = target.call{value: msg.value}("");
        require(s);
    }
}

