import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // keep amount within a wide but admissible domain: up to 1 ether
        amount = bound(amount, 0, 1 ether);

        // Deploy an adversarial recipient that ALWAYS reverts on receive/call
        Reverter r = new Reverter();

        // Fund the contract so withdraw can attempt to send
        address deployer = address(this); // owner is deployer of c in setUp()
        vm.deal(address(c), 1 ether);

        // Ensure we're acting as the owner when calling withdraw
        vm.prank(deployer);

        // Call sendMoney to set up potential state (not strictly required, but keep general)
        // Now attempt withdraw to the adversarial recipient by making the owner call withdraw
        // We can't change C.withdraw signature, so we simulate by making msg.sender the owner
        // and then expecting the transfer/call to the owner (this test uses owner as recipient that reverts)

        // Make this contract the owner by virtue of deployment in setUp(); but the recipient that will receive
        // funds when withdraw calls payable(msg.sender) is msg.sender (the owner). To make that call hit
        // a reverting recipient, we must have msg.sender be the Reverter contract. So we impersonate the Reverter
        // as msg.sender while having the Reverter contract perform the withdraw. To do that, we fund the Reverter
        // and have it call c.withdraw as owner via vm.prank with its address.

        // Give the reverter enough ETH so that if the reference uses transfer it can receive; but it will revert anyway.
        vm.deal(address(r), 0);

        // Now have the Reverter call withdraw with amount. The Reverter contract's fallback/receive reverts,
        // so in the reference (which uses transfer) the transfer will revert and the withdraw should revert.
        // In the mutant (which uses call and ignores success) the call will return false and withdraw will not revert,
        // leaving address(c).balance unchanged. We'll detect the difference by observing address(c).balance change

        uint256 before = address(c).balance;
        bool ok;
        // Reverter must be msg.sender for withdraw to attempt sending to it, so prank as r and call withdraw
        vm.prank(address(r));
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 afterBal = address(c).balance;

        // General rule: for the correct contract, when the recipient reverts on receiving funds, withdraw MUST revert
        // and therefore contract balance remains unchanged (ok == false and afterBal == before). For the mutant,
        // withdraw may return successfully (ok == true) while afterBal == before (silent failure). We assert the
        // universal property that if the call returned successfully then the contract balance decreased by amount
        // (i.e., successful withdraw actually transfers funds). This holds for the reference for all inputs; the
        // mutant will fail for some input (reverting recipient) where ok == true but balance did not decrease.

        // Single assertion reading c's observable behavior:
        // If the withdraw call returned successfully, address(c).balance must have decreased by exactly amount.
        if (ok) {
            assertTrue(afterBal + amount == before);
        } else {
            // If it reverted, then balance must be unchanged
            assertTrue(afterBal == before);
        }
    }
}

